type RewardKind = 'shop' | 'badge';

function emptyRewardDraft(): Reward {
  return {
    id: '',
    title: '',
    description: '',
    cost: 50,
  };
}

function RewardAdmin() {
  const { state, addReward, updateReward, deleteReward } = useAppStore();
  const [draft, setDraft] = useState<Reward>(emptyRewardDraft());
  const [kind, setKind] = useState<RewardKind>('shop');
  const [streakDays, setStreakDays] = useState(7);
  const [levelTarget, setLevelTarget] = useState(2);
  const [message, setMessage] = useState('');

  const loadDraft = (reward: Reward) => {
    setDraft(reward);
    if (reward.autoTrigger?.type === 'streak') {
      setKind('badge');
      setStreakDays(reward.autoTrigger.days);
    } else if (reward.autoTrigger?.type === 'level') {
      setKind('badge');
      setLevelTarget(reward.autoTrigger.level);
    } else {
      setKind('shop');
    }
  };

  const buildReward = (): Reward => {
    const base: Reward = {
      id: draft.id || newId('reward'),
      title: draft.title.trim(),
      description: draft.description.trim(),
    };
    if (kind === 'shop') {
      return { ...base, cost: draft.cost ?? 50, autoTrigger: undefined };
    }
  const trigger: RewardTrigger =
      kind === 'badge' && streakDays > 0
        ? { type: 'streak', days: streakDays }
        : { type: 'level', level: levelTarget };
    return { ...base, cost: undefined, autoTrigger: trigger };
  };

  const submit = () => {
    if (!draft.title.trim()) return;
    const reward = buildReward();
    if (state.rewards.some((r) => r.id === reward.id)) updateReward(reward);
    else addReward(reward);
    setDraft(emptyRewardDraft());
    setKind('shop');
    setMessage('Reward saved.');
  };

  const remove = (id: string) => {
    if (!window.confirm('Delete this reward from the catalog?')) return;
    deleteReward(id);
    if (draft.id === id) setDraft(emptyRewardDraft());
    setMessage('Reward deleted.');
  };

  return (
    <section className="card">
      <p className="muted">
        Shop rewards cost points; badges unlock automatically from streaks or
        levels.
      </p>
      {message && <p className="notice">{message}</p>}
      <ul className="edit-list">
        {state.rewards.length === 0 && (
          <li className="muted">No rewards yet. Create one below.</li>
        )}
        {state.rewards.map((r) => (
          <li key={r.id} className="edit-list__row">
            <button
              type="button"
              className="edit-list__btn"
              onClick={() => loadDraft(r)}
            >
              {r.title}
              {r.cost != null ? ` (${r.cost} pts)` : ' (badge)'}
            </button>
            <button
              type="button"
              className="btn btn--ghost btn--small"
              onClick={() => remove(r.id)}
            >
              Delete
            </button>
          </li>
        ))}
      </ul>
      <motion.div className="form-grid">
        <input
          placeholder="Title"
          value={draft.title}
          onChange={(e) => setDraft({ ...draft, title: e.target.value })}
        />
        <input
          placeholder="Description"
          value={draft.description}
          onChange={(e) => setDraft({ ...draft, description: e.target.value })}
        />
        <select
          value={kind}
          onChange={(e) => setKind(e.target.value as RewardKind)}
          aria-label="Reward type"
        >
          <option value="shop">Shop (points)</option>
          <option value="badge">Badge (auto unlock)</option>
        </select>
        {kind === 'shop' ? (
          <input
            type="number"
            min={1}
            aria-label="Point cost"
            value={draft.cost ?? 50}
            onChange={(e) =>
              setDraft({ ...draft, cost: Number(e.target.value) })
            }
          />
        ) : (
          <>
            <input
              type="number"
              min={1}
              aria-label="Streak days"
              placeholder="Streak days (0 = use level)"
              value={streakDays}
              onChange={(e) => setStreakDays(Number(e.target.value))}
            />
            <input
              type="number"
              min={1}
              max={5}
              aria-label="Level target"
              value={levelTarget}
              onChange={(e) => setLevelTarget(Number(e.target.value))}
            />
          </>
        )}
      </div>
      <button type="button" className="btn btn--primary" onClick={submit}>
        {draft.id ? 'Update reward' : 'Create reward'}
      </button>
    </section>
  );
}

function PunishmentTemplateAdmin() {
  const {
    state,
    addPunishmentTemplate,
    updatePunishmentTemplate,
    deletePunishmentTemplate,
  } = useAppStore();
  const [draft, setDraft] = useState<PunishmentTemplate>({
